import datetime
import re

from ta_moler.events.rtg.genericrtg_lineevent import GenericRtgLineEvent


class DspCrash(GenericRtgLineEvent):
    """DSP crash event class."""

    # Example line: 06:43:13|DSP crash detected on [ctrl_6] in syslog line:
    re_dsp_crash_detected = re.compile(r"DSP crash detected on \[(?P<CTRL>ctrl_\d+)] in syslog line:")

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """Event for dsp crash.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param runner: Runner to run event
        """
        super(DspCrash, self).__init__(
            connection=connection, runner=runner, till_occurs_times=till_occurs_times, detect_patterns=[self.re_dsp_crash_detected], match="any"
        )


EVENT_OUTPUT = """
06:43:13|DSP crash detected on [ctrl_6] in syslog line:
06:43:13|**********************************************************************
06:43:13|14.06:43:13.751| 35 FW2-123D-0-CCSLite <2019-06-14T04:43:13.666689Z> 17D0-LITE_STARTUP_SERVIC ERR/CCSLiteExe 0x1239 has crashed. Core dump /var/tmp/diagn/CCSLiteExe_6122_.core.xz
06:43:13|**********************************************************************
06:43:13|c6|Collecting memdump"""

